"""Render the completed, independently scored autonomous trial."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1];directory=json.loads((R/'reports/latest-full-mapping-test.json').read_text())['directory'];D=R/'reports'/directory;r=json.loads((D/'results.json').read_text());trial=json.loads((D/'trial.json').read_text());e=html.escape
prefix='reports/'+directory+'/'
rows=''.join(f'<tr><td>{e(x["room"])}</td><td>{"Yes" if x["entered"] else "No"}</td><td>{100*x["mapped_free_fraction"]:.1f}%</td><td>{100*x["observed_fraction"]:.1f}%</td></tr>' for x in r['rooms'])
status='Full-house mapping passed' if r['passed'] else 'The robot did not finish mapping the house'
reason=e(r['robot_stop_reason']);minutes=r['duration_sim_s']/60
termination=e(trial.get('termination','Unknown termination'))
setup=json.loads((D/'test-setup.json').read_text()) if (D/'test-setup.json').exists() else {}
start_description=('Before this trial the simulator was reset to its standard starting position. No resets occurred after Mapping started.' if setup.get('reset_to_standard_spawn') else 'Mapping started at the existing physical position, without repositioning the robot.')

unaided=len(trial['external_actions'])==1 and trial['external_actions'][0]=={'mode':'mapping'}
policy=('The only external command was Start Mapping. All movement, viewpoint selection and stopping decisions came from the robot.' if unaided else 'The robot selected its own movements and viewpoints. An external stop ended this trial; the action log below records it.')
changes=('Controller files remained unchanged throughout this trial.' if trial.get('source_unchanged') else 'The source-integrity check did not confirm an unchanged controller.')
trace=[json.loads(line)['status'] for line in (D/'trace.jsonl').read_text().splitlines()]
events=[]
for state in trace:
 for event in state.get('events',[]):
  if event not in events:events.append(event)
event_rows=''.join('<li>'+e(event['message'])+'</li>' for event in events[-10:])
diagnosis_link=('<a href="'+prefix+'obstacle-diagnosis.json">Obstacle diagnosis</a> · ' if (D/'obstacle-diagnosis.json').exists() else '')

report=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Full-house autonomous mapping test</title><style>
*{{box-sizing:border-box}}body{{background:#f0f4f1;color:#26382e;font:16px/1.6 system-ui,sans-serif;margin:0}}main{{max-width:1080px;margin:auto;padding:40px 24px}}h1{{font-size:clamp(30px,5vw,49px);line-height:1.12;letter-spacing:-1.2px}}h2{{font-size:24px;margin-top:34px}}.eyebrow{{font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#597365}}.note{{padding:20px;border:1px solid #d6bc95;background:#fff4e2;border-radius:10px}}.cards{{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}}.card{{padding:20px;background:white;border:1px solid #d4dfd6;border-radius:10px}}.card b{{display:block;font-size:29px}}a{{color:#276c51}}img{{width:100%;display:block;border-radius:8px}}figure{{margin:24px 0}}figcaption,.small{{font-size:13px;color:#597062}}table{{width:100%;border-collapse:collapse;background:white}}th,td{{text-align:left;padding:13px;border-bottom:1px solid #d5dfd8}}th{{font-size:13px}}nav{{display:flex;gap:20px;flex-wrap:wrap}}@media(max-width:650px){{.cards{{grid-template-columns:1fr}}}}
</style><main><div class="eyebrow">One start command · robot-controlled movement · independent scoring</div><h1>{status}</h1><p>Mapping used a fresh map. {start_description} The robot selected all targets, planned all paths and issued every movement command. {policy} {changes}</p><nav><a href="http://127.0.0.1:8771/autonomy.html">Robot controls</a><a href="house-preview.html">House preview</a><a href="simulation-review.html">Earlier tests</a></nav><div class="cards"><div class="card"><b>{r['rooms_entered']} / {r['reference_room_count']}</b>rooms physically entered</div><div class="card"><b>{100*r['mapped_free_fraction']:.1f}%</b>reference navigable space mapped free</div><div class="card"><b>{minutes:.1f} min</b>simulation time</div></div><div class="note"><b>The robot’s own stop reason:</b><br>{reason}<p>The saved map is {"marked complete" if r['robot_map_complete'] else "marked partial"}. A full-house pass requires every reachable room to be entered and at least 90% of each room’s conservative navigable space to be classified free.</p></div><figure><img src="{prefix}coverage-and-path.png" alt="Independent map coverage and recorded robot trajectory"><figcaption>House geometry and actual simulator position are used here only to score the result. They are not supplied to the robot controller. Amber areas remain unmapped or are not classified as free.</figcaption></figure><h2>Room-by-room results</h2><table><thead><tr><th>Room</th><th>Entered</th><th>Mapped free</th><th>Observed at least once</th></tr></thead><tbody>{rows}</tbody></table><p class="small">The denominator is space reachable by a robot center with 19 cm clearance from the reference collision boxes. It excludes inaccessible furniture areas and the raised shower tray. Merely seeing through a doorway does not count as entering a room.</p><h2>What happened</h2><p>{termination}. The robot traveled {r['distance_traveled_m']:.2f} m and entered {r['rooms_entered']} of {r['reference_room_count']} reference rooms. The map is recorded as {"complete" if r['robot_map_complete'] else "partial"}.</p><p>These are the last recorded controller decisions:</p><ul>{event_rows}</ul><figure><img src="{prefix}final-camera.png" alt="Final robot camera view"><figcaption>The robot’s final left-camera view. No obstacle was moved or removed.</figcaption></figure><h2>Controller changes tested</h2><ul><li>Separate forward clearance from turning clearance; retain obstacle evidence when replanning.</li><li>Prefer viewpoints with clearance and visible landmarks. Return toward the last useful view when tracking fails.</li><li>Require repeated saved-landmark matches after lost tracking. Freeze map updates until localization is recovered.</li><li>Correct wheel-axle offset and camera-pose fusion. Treat contact, slipping and blocked turns as position uncertainty.</li><li>Keep progress deadlines across replans and report motor or connection failures as explicit stops.</li></ul><p><a href="reports/autonomy-unit-tests.txt">Regression test results</a>. These checks complement the actual Unreal trial; they do not prove full-house mapping on their own.</p><h2>Recorded evidence</h2><p><a href="{prefix}results.json">Evaluation results</a> · <a href="{prefix}trial.json">Trial setup and unchanged-code hashes</a> · <a href="{prefix}trace.jsonl">Recorded decisions and evaluation positions</a> · <a href="{prefix}map-manifest.json">Saved map status</a> · {diagnosis_link}<a href="{prefix}final-status.json">Final robot status</a></p><p class="small">Position error includes a small timing difference between camera captures and status updates. Surface appearance, stereo cameras and physical contact are approximations. This test does not validate real-home or Jetson performance.</p></main></html>'''
(R/'full-mapping-review.html').write_text(report);print(R/'full-mapping-review.html')
